export type CategoryId = "all" | "keynote-deck" | "scroll-showcase" | "3d-webgpu" | "editorial-magazine" | "conversion";

export type TemplateCategory = Exclude<CategoryId, "all">;

export interface Category {
  id: CategoryId;
  label: string;
}

export interface TemplateItem {
  slug: TemplateSlug;
  createdAt: string;
  /** Derived from append order; later registrations win same-day ties. */
  registrationOrder: number;
  hasDownload?: boolean;
  title: string;
  description: string;
  category: TemplateCategory;
  industry: string;
  stack: string;
  badges: string[];
  previewImage: string;
  videoClip?: string;
  promptMarkdown: string;
  model: string;
  archived?: boolean;
}

